package com.bananalab.lite;
import android.app.*;import android.content.*;import android.os.*;
/** Foreground service only for the user's explicit, visible on-device training task. */
public final class LearningService extends Service{
 static final int NOTICE=6602;static final String CHANNEL="banana-learning";Thread task;volatile boolean stopping;
 Notification notification(String text){NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel channel=new NotificationChannel(CHANNEL,"Aprendizaje de Banana",NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);channel.enableVibration(false);manager.createNotificationChannel(channel);}int flags=PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=23?PendingIntent.FLAG_IMMUTABLE:0);PendingIntent open=PendingIntent.getActivity(this,1,new Intent(this,StartActivity.class),flags),pause=PendingIntent.getService(this,2,new Intent(this,LearningService.class).setAction("pause"),flags);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_popup_sync).setContentTitle("Banana · aprendizaje continuo").setContentText(text).setContentIntent(open).setOngoing(true).setOnlyAlertOnce(true).setPriority(Notification.PRIORITY_LOW).addAction(android.R.drawable.ic_media_pause,"Pausar",pause).build();}
 void show(String text){try{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTICE,notification(text));}catch(Exception ignored){}}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"pause".equals(intent.getAction())){try{LearningLoop.pause(this);}catch(Exception e){LearningLoop.status(this,"Pausa solicitada: "+e.getClass().getSimpleName());}stopSelf();return START_NOT_STICKY;}if(!LearningLoop.enabled(this)){stopSelf();return START_NOT_STICKY;}try{Notification note=notification("Preparando lecturas pendientes");if(Build.VERSION.SDK_INT>=34)startForeground(NOTICE,note,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(NOTICE,note);}catch(Exception e){LearningLoop.status(this,"Android no permitió iniciar el aprendizaje visible: "+e.getClass().getSimpleName());stopSelf();return START_NOT_STICKY;}if(task!=null&&task.isAlive())return START_STICKY;LearningLoop.serviceRunning=true;stopping=false;task=new Thread(new Runnable(){public void run(){LearningLoop.worker=Thread.currentThread();int failures=0;try{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);while(!stopping&&LearningLoop.enabled(LearningService.this)&&!Thread.currentThread().isInterrupted()){String why=LearningLoop.conditions(LearningService.this);if(!why.isEmpty()){LearningLoop.status(LearningService.this,"En espera: "+why);show("En espera: "+why);Thread.sleep(LearningPlan.delay(why,failures));continue;}PowerManager.WakeLock wake=null;try{PowerManager power=(PowerManager)getSystemService(POWER_SERVICE);if(power!=null){wake=power.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Banana:learning");wake.acquire(8*60*1000L);}show("Entrenando y comprobando ejercicios de tus fuentes");boolean more=LearningLoop.cycle(LearningService.this);if(!more)break;failures=0;}catch(ReadingBudget.Paused pause){failures++;LearningLoop.status(LearningService.this,"En espera: "+pause.getMessage());show("En espera: "+pause.getMessage());}catch(InterruptedException stopped){Thread.currentThread().interrupt();break;}catch(Exception failure){failures++;LearningLoop.status(LearningService.this,"Tanda pendiente: "+AndroidRepair.summary(failure));show("Tanda pendiente; conservé el último modelo válido");}finally{if(wake!=null&&wake.isHeld())wake.release();}Thread.sleep(LearningPlan.delay("",failures));}}catch(InterruptedException stopped){Thread.currentThread().interrupt();}finally{if(LearningLoop.worker==Thread.currentThread())LearningLoop.worker=null;LearningLoop.serviceRunning=false;LearningLoop.configure(LearningService.this);stopSelf();}}},"banana-continuous-learning");task.start();return START_STICKY;}
 @Override public IBinder onBind(Intent intent){return null;}
 @Override public void onDestroy(){stopping=true;if(task!=null)task.interrupt();stopForeground(true);super.onDestroy();}
 @Override public void onTimeout(int startId,int type){LearningLoop.status(this,"Android agotó el tiempo permitido; progreso conservado");stopping=true;if(task!=null)task.interrupt();stopForeground(true);stopSelf();}
}
